<script setup>
import { ref, reactive, computed, watch, onMounted, onBeforeUnmount } from 'vue'
import { useRoute, useRouter, onBeforeRouteLeave } from 'vue-router'
import Splitter from 'primevue/splitter'
import SplitterPanel from 'primevue/splitterpanel'
import Dialog from 'primevue/dialog'
import Drawer from 'primevue/drawer'
import InputText from 'primevue/inputtext'
import Button from 'primevue/button'
import { useConfirm } from 'primevue/useconfirm'
import { useToast } from 'primevue/usetoast'
import { ArrowLeft, PanelLeft, PanelRight, Save, LockKeyhole, ShieldCheck, Download, FileCode2 } from 'lucide-vue-next'
import { api } from '../../services/api'
import { projects } from '../../stores/projects'
import { session } from '../../stores/session'
import { workspace } from '../../stores/workspace'
import { collaboration } from '../../stores/collaboration'
import MonacoPane from '../../components/workspace/MonacoPane.vue'
import ExplorerPane from '../../components/workspace/ExplorerPane.vue'
import ContextPane from '../../components/workspace/ContextPane.vue'
import PermissionsDialog from '../../components/workspace/PermissionsDialog.vue'
import DevelopmentTools from '../../components/workspace/DevelopmentTools.vue'
import TerminalPane from '../../components/workspace/TerminalPane.vue'
import FileConflict from '../../components/workspace/FileConflict.vue'
import { development as dev } from '../../stores/development'
import ProjectState from '../../components/project/ProjectState.vue'
const route=useRoute(),router=useRouter(),confirm=useConfirm(),toast=useToast()
const nodeDialog=ref(false),nodeForm=reactive({name:'',kind:'file',parent:null,rename:null}),nodeBusy=ref(false),nodeError=ref(''),permissionNode=ref(),explorerDrawer=ref(false),contextDrawer=ref(false),contextTab=ref(route.query.task?'task':'comments'),selection=ref({line_start:1,line_end:1}),taskId=ref(Number(route.query.task) || null)
const narrow=ref(window.innerWidth<1100)
const editable=computed(()=>!workspace.state.active?.binary && ['EDIT','FULL_ACCESS'].includes(workspace.state.active?.permission))
const peers=computed(()=>collaboration.state.users.filter(p=>p.node_id===workspace.state.active?.id && p.user.id!==session.state.user.id))
function paletteCreate(){create({kind:'file',parent:null})}
function resize(){narrow.value=window.innerWidth<1100}
async function refresh(){try{await workspace.refresh()}catch(e){workspace.state.error=e.friendly}}
async function open(node){
  if(node.id===workspace.state.active?.id)return
  if(workspace.dirty.value && !window.confirm('Switch files? Your unsaved draft will be preserved in this browser session.'))return
  await router.replace({path:'/workspace',query:{file:node.id,task:taskId.value || undefined}})
  explorerDrawer.value=false
}
function create({kind,parent}){Object.assign(nodeForm,{name:'',kind,parent,rename:null});nodeError.value='';nodeDialog.value=true}
function rename(node){Object.assign(nodeForm,{name:node.name,kind:node.kind,parent:null,rename:node});nodeError.value='';nodeDialog.value=true}
async function saveNode(){nodeBusy.value=true;nodeError.value='';try{const {data}=nodeForm.rename?await api.patch(`/workspace/nodes/${nodeForm.rename.id}`,{name:nodeForm.name,version:nodeForm.rename.version}):await api.post(`/projects/${projects.state.activeId}/workspace`,{name:nodeForm.name,kind:nodeForm.kind,parent_id:nodeForm.parent?.id || null});await workspace.refresh();nodeDialog.value=false;if(data.node.kind==='file')await open(data.node);toast.add({severity:'success',summary:nodeForm.rename?'Node renamed':'Workspace node created',life:2500})}catch(e){nodeError.value=e.friendly}finally{nodeBusy.value=false}}
function remove(node){confirm.require({header:`Delete ${node.kind}?`,message:`${node.path}${node.kind==='folder'?' and all descendants':''} will be permanently deleted, including links and code comments.`,acceptLabel:'Delete',rejectLabel:'Cancel',acceptProps:{severity:'danger'},accept:async()=>{try{if(workspace.state.active?.id===node.id && workspace.dirty.value)workspace.downloadDraft();await api.delete(`/workspace/nodes/${node.id}`);await refresh();toast.add({severity:'success',summary:'Node deleted',life:2500})}catch(e){workspace.state.error=e.friendly}}})}
async function save(){if(await workspace.save()){collaboration.editing(false);toast.add({severity:'success',summary:'File saved',life:2000})}}
function keydown(event){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();save()}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='p'){event.preventDefault();projects.state.palette=true}}
function beforeUnload(event){if(workspace.dirty.value){workspace.draft();event.preventDefault();event.returnValue=''}}
function select(value){selection.value={line_start:value.line_start,line_end:value.line_end};collaboration.editing(workspace.dirty.value,value.cursor)}
function changed(value){workspace.edit(value);collaboration.editing(true)}
function commentLine(line){selection.value={line_start:line,line_end:line};contextTab.value='comments';if(narrow.value)contextDrawer.value=true;else workspace.state.context=true}
watch(()=>route.query.file,async value=>{if(value){await workspace.open(Number(value));selection.value={line_start:1,line_end:1};await collaboration.context()}},{immediate:true})
watch(()=>route.query.task,value=>{taskId.value=Number(value)||null;if(value)contextTab.value='task'})
onMounted(async()=>{workspace.state.inWorkspace=true;collaboration.context();window.addEventListener('teamflow-create-file',paletteCreate);window.addEventListener('resize',resize);window.addEventListener('keydown',keydown);window.addEventListener('beforeunload',beforeUnload);try{await workspace.tree();await dev.load()}catch(e){workspace.state.error=e.friendly}})
onBeforeUnmount(()=>{workspace.state.inWorkspace=false;collaboration.context();window.removeEventListener('teamflow-create-file',paletteCreate);window.removeEventListener('resize',resize);window.removeEventListener('keydown',keydown);window.removeEventListener('beforeunload',beforeUnload);workspace.draft();collaboration.editing(false)})
onBeforeRouteLeave(()=>!workspace.dirty.value || window.confirm('Leave the workspace? Your unsaved draft will remain in this browser session.'))
</script>
<template><ProjectState><section class="development-workspace"><header class="workspace-toolbar"><div class="workspace-toolbar-left"><RouterLink to="/" class="icon-button" aria-label="Back to project"><ArrowLeft :size="17"/></RouterLink><span class="workspace-title">Development workspace</span><span class="workspace-file-path">{{ workspace.state.active?.path || projects.active.value?.name }}</span></div><div class="workspace-toolbar-actions"><button class="icon-button" aria-label="Toggle file explorer" title="File explorer" :aria-pressed="narrow?explorerDrawer:workspace.state.explorer" @click="narrow?explorerDrawer=!explorerDrawer:workspace.state.explorer=!workspace.state.explorer"><PanelLeft :size="17"/></button><button class="icon-button" aria-label="Toggle context panel" title="Context / discussion" :aria-pressed="narrow?contextDrawer:workspace.state.context" @click="narrow?contextDrawer=!contextDrawer:workspace.state.context=!workspace.state.context"><PanelRight :size="17"/></button><button v-if="session.state.team.role==='LEADER' && workspace.state.active" class="icon-button" aria-label="Manage active file permissions" title="Permissions" @click="permissionNode=workspace.state.active"><ShieldCheck :size="17"/></button><span v-if="workspace.state.active?.kind==='file'" class="save-state" aria-live="polite">{{ workspace.state.saving?'Saving…':workspace.state.conflict?'Conflict':workspace.state.error?'Save failed':!editable?'Read only':workspace.dirty.value?'Unsaved changes':'Saved' }}</span><Button v-if="editable" label="Save" size="small" :loading="workspace.state.saving" :disabled="!workspace.dirty.value" @click="save"><template #icon><Save :size="14"/></template></Button></div></header><p v-if="workspace.state.error" class="workspace-error form-error" role="alert">{{ workspace.state.error }}<button class="text-button" @click="refresh">Retry refresh</button></p><FileConflict/><div class="development-actions"><Button v-if="dev.state.canManage" label="Project settings" severity="secondary" @click="dev.state.settings=true"/><Button v-if="dev.state.canManage && !workspace.state.nodes.length" label="Import existing project" severity="secondary" @click="dev.state.importDialog=true"/><Button v-if="dev.state.canManage" label="Download project" severity="secondary" :loading="dev.state.busy" @click="dev.download"/><template v-if="dev.state.canExecute"><Button label="Run project" :loading="dev.state.busy" :disabled="dev.state.execution?.status==='running'" @click="dev.start('run')"/><Button label="Run tests" severity="secondary" :loading="dev.state.busy" :disabled="dev.state.execution?.status==='running'" @click="dev.start('test')"/><Button label="Terminal" severity="secondary" @click="dev.state.terminal=!dev.state.terminal"/><span class="test-state">{{ !dev.state.config?.test_command?'Tests not configured':dev.state.latestTest?`Tests ${dev.state.latestTest.status}${dev.state.latestTest.fingerprint!==dev.state.fingerprint?' · saved files changed':''}`:'Tests not run' }}</span></template></div><p v-if="dev.state.error && !dev.state.terminal" class="form-error workspace-error" role="alert">{{ dev.state.error }}</p><Splitter class="workspace-panels"><SplitterPanel v-if="!narrow && workspace.state.explorer" :size="20" :minSize="15" key="explorer"><ExplorerPane @open="open" @create="create" @rename="rename" @delete="remove" @permissions="permissionNode=$event" @refresh="refresh"/></SplitterPanel><SplitterPanel :size="58" :minSize="35" key="editor"><div class="workspace-editor"><div v-if="workspace.state.loading" class="compact-empty">Opening file…</div><template v-else-if="workspace.state.active?.kind==='file'"><div class="editor-tab"><FileCode2 :size="14"/><span>{{ workspace.state.active.name }}</span><i v-if="workspace.dirty.value" class="unsaved-dot"></i><span v-if="!editable" class="readonly-label"><LockKeyhole :size="12"/> Read only</span><small>v{{ workspace.state.version }}</small></div><div v-if="workspace.state.active.binary" class="workspace-welcome"><FileCode2 :size="30"/><h2>Binary project asset</h2><p>This asset is preserved in the online workspace, execution snapshots and exported ZIP.</p><Button label="Download asset" @click="workspace.downloadAsset"/></div><MonacoPane v-else :key="workspace.state.active.id" :node="workspace.state.active" :text="workspace.state.text" :readonly="!editable" :comments="workspace.state.detail?.comments" :peers="peers" @change="changed" @save="save" @selection="select" @focus="collaboration.editing(workspace.dirty.value)" @blur="collaboration.editing(false)" @comment-line="commentLine"/><footer class="editor-status"><span>Line {{ selection.line_start }} · UTF-8</span><span>{{ workspace.state.active.permission.replaceAll('_',' ') }} · Explicit save · Ctrl / ⌘ S</span></footer></template><div v-else class="workspace-welcome"><span class="workspace-welcome-icon"><FileCode2 :size="30"/></span><span class="eyebrow">CONNECTED CODE</span><h2>Build with the whole picture.</h2><p>Open a project file to edit, discuss saved lines, and see the work it belongs to.</p><Button v-if="narrow" label="Explore files" severity="secondary" @click="explorerDrawer=true"/><p class="field-hint">Ctrl / ⌘ K to search · Ctrl / ⌘ S to save</p></div></div></SplitterPanel><SplitterPanel v-if="!narrow && workspace.state.context" :size="22" :minSize="18" key="context"><ContextPane :selection="selection" :taskId="taskId" :tab="contextTab" @tab="contextTab=$event" @task="taskId=$event"/></SplitterPanel></Splitter><TerminalPane v-if="dev.state.terminal && dev.state.canExecute"/><DevelopmentTools/><Drawer v-model:visible="explorerDrawer" header="Project files" class="workspace-explorer-drawer"><ExplorerPane @open="open" @create="create" @rename="rename" @delete="remove" @permissions="permissionNode=$event" @refresh="refresh"/></Drawer><Drawer v-model:visible="contextDrawer" position="right" header="File context" class="workspace-context-drawer"><ContextPane :selection="selection" :taskId="taskId" :tab="contextTab" @tab="contextTab=$event" @task="taskId=$event"/></Drawer><Dialog v-model:visible="nodeDialog" modal :header="nodeForm.rename?'Rename node':`Create ${nodeForm.kind}`" :style="{width:'430px'}" :breakpoints="{'500px':'94vw'}" :closable="!nodeBusy"><form class="form-stack" @submit.prevent="saveNode"><p class="field-hint">{{ nodeForm.rename?.path || nodeForm.parent?.path || 'Project root' }}</p><label for="node-name">{{ nodeForm.kind==='folder'?'Folder name':'File name' }}</label><InputText id="node-name" v-model="nodeForm.name" required maxlength="120" autofocus :disabled="nodeBusy" :placeholder="nodeForm.kind==='folder'?'Folder name':'File name, including extension'"/><p v-if="nodeError" class="form-error" role="alert">{{ nodeError }}</p><Button type="submit" :label="nodeForm.rename?'Rename':'Create'" :loading="nodeBusy"/></form></Dialog><PermissionsDialog v-model="permissionNode"/></section></ProjectState></template>


